    return incompletePartitionsTimeline;
  }
  return completePartitionsTimeline;
}

/**
 * Copies only the visible partition chunks of a timeline entry and clips the holder to the query interval.
 */
@GuardedBy("lock")
private TimelineObjectHolder<VersionType, ObjectType> copyWithOnlyVisibleChunks(
    Interval queryInterval,
    Interval timelineInterval,
    Interval trueInterval,
    VersionType version,
    PartitionHolder<ObjectType> partitionHolder,
    boolean skipEmpty
)
{
  Preconditions.checkState(
      lock.getReadHoldCount() > 0 || lock.isWriteLockedByCurrentThread(),
      "timeline must be locked during visible holder copy"
  );
  final boolean skipNoData = skipObjectsWithNoData;
  if (skipEmpty && skipNoData && !partitionHolder.hasData()) {
    return null;
  }

  DateTime timelineStart = timelineInterval.getStart();
  DateTime timelineEnd = timelineInterval.getEnd();
  DateTime queryStart = queryInterval.getStart();
  DateTime queryEnd = queryInterval.getEnd();
  if (!(timelineStart.getMillis() < queryEnd.getMillis() && queryStart.getMillis() < timelineEnd.getMillis())) {
    return null;
  }

  List<PartitionChunk<ObjectType>> visibleChunks = new ArrayList<>();
  for (PartitionChunk<ObjectType> chunk : partitionHolder) {
    visibleChunks.add(chunk);
  }
  TimelineObjectHolder<VersionType, ObjectType> holder = new TimelineObjectHolder<>(
      timelineInterval,
      trueInterval,
      version,
      new PartitionHolder<>(visibleChunks)
  );

  Interval holderInterval = holder.getInterval();
  DateTime overlapStart = JodaUtils.maxDateTime(queryInterval.getStart(), holderInterval.getStart());
  DateTime overlapEnd = JodaUtils.minDateTime(queryInterval.getEnd(), holderInterval.getEnd());
  if (overlapStart.getMillis() < overlapEnd.getMillis()) {
    Interval clipped;
    if (ISOChronology.getInstanceUTC().equals(holderInterval.getChronology())) {
      clipped = Intervals.utc(overlapStart.getMillis(), overlapEnd.getMillis());
    } else {
      clipped = new Interval(overlapStart.getMillis(), overlapEnd.getMillis(), holderInterval.getChronology());
    }
    return new TimelineObjectHolder<>(
        clipped,
        holder.getTrueInterval(),
        holder.getVersion(),
        holder.getObject()
    );
  }
  return holder;
}

